import { HubConnectionBuilder } from "@microsoft/signalr";
import { Activity, ArchiveRestore, Boxes, CirclePlay, CircleStop, Download, FolderArchive, Gamepad2, HeartPulse, LogOut, RefreshCw, Save, Search, Settings2, TerminalSquare, Trash2, Upload, Users } from "lucide-react";
import { type ChangeEvent, type FormEvent, useCallback, useEffect, useState } from "react";
import { Button } from "./components/ui/button";
import { Card } from "./components/ui/card";

type State = "stopped" | "starting" | "running" | "stopping" | "failed";
type Status = { state: State; processId?: number; message?: string };
type ResourceSettings = { frequency: string; size: string; richness: string };
type MapGeneration = { seed?: number; width: number; height: number; water: string; startingArea: string; terrainSegmentation: string; peacefulMode: boolean; ironOre: ResourceSettings; copperOre: ResourceSettings; stone: ResourceSettings; coal: ResourceSettings; uraniumOre: ResourceSettings; crudeOil: ResourceSettings; trees: ResourceSettings; enemyBase: ResourceSettings; evolutionTime: number; evolutionPollution: number; evolutionDestroy: number; enemyExpansionEnabled: boolean; enemyExpansionMinDistance: number; enemyExpansionMaxDistance: number; settlerGroupMinSize: number; settlerGroupMaxSize: number; expansionMinCooldown: number; expansionMaxCooldown: number; cliffElevationInterval: number; cliffElevationOffset: number; cliffRichness: string };
type Settings = { serverName: string; description: string; maxPlayers: number; visibilityPublic: boolean; autosaveMinutes: number; activeSave?: string; channel: "stable" | "experimental"; activeVersion?: string; backupIntervalHours: number; backupRetention: number; timeZone: string; mapGeneration: MapGeneration };
type UpdateStatus = { availableVersion?: string; checkedVersion?: string; checkedAt: string; error?: string };
type SystemHealth = { checkedAt: string; uptimeSeconds: number; workingSetBytes: number; dataFreeBytes?: number; dataTotalBytes?: number; saveCount: number; backupCount: number; versionCount: number; modFileCount: number; databasePresent: boolean };
type MaintenanceStatus = { checkedAt: string; backupIntervalHours: number; backupRetention: number; lastScheduledBackup?: string; nextScheduledBackup?: string; lastUpdateCheck?: string; nextUpdateCheck?: string };
type Mod = { name: string; version: string; enabled: boolean; dependencies?: string[]; source?: "portal" | "local"; archiveFileName?: string; sha256?: string; factorioVersionRequirement?: string };
type ModUpdateInfo = { name: string; installedVersion: string; latestVersion?: string; updateAvailable: boolean; missingDependencies: string[]; downloadUrl?: string };
type ModProfile = { name: string; mods: Array<{ name: string; version: string; enabled: boolean }>; createdAt: string; updatedAt: string };
type PortalMod = { name: string; title?: string; summary?: string };
type ModRecovery = { pending: boolean; message?: string; quarantinedFiles: string[]; startedAt?: string };
type ModPreflight = { operation: string; allowed: boolean; requiresBackup: boolean; activeSave?: string; activeVersion?: string; plannedMods: Mod[]; blockers: string[]; warnings: string[]; downloads: string[] };
type Tab = "overview" | "settings" | "versions" | "mods" | "saves" | "players" | "logs" | "health" | "users" | "audit";
type Me = { csrfToken: string; uid?: string; name?: string; role?: "owner" | "admin" | "viewer" };
type User = { id: string; username: string; role: "owner" | "admin" | "viewer" };
type AuditEvent = { id: number; occurredAtUtc: string; action: string; targetType: string; outcome: string; actorUserId?: string };
type LivePlayer = { name: string; onlineSinceSeconds?: number };
type Action = (path: string, init?: RequestInit) => Promise<boolean>;
let csrf = "";
async function api<T>(path: string, init: RequestInit = {}): Promise<T> {
  const headers = new Headers(init.headers);
  if (init.method && !["GET", "HEAD"].includes(init.method)) headers.set("X-CSRF-Token", csrf);
  if (init.body && !(init.body instanceof FormData)) headers.set("Content-Type", "application/json");
  const response = await fetch(path, { ...init, headers, credentials: "same-origin" });
  if (!response.ok) throw new Error((await response.json().catch(() => ({ error: response.statusText }))).error ?? response.statusText);
  return response.status === 204 ? undefined as T : response.json() as Promise<T>;
}

function Auth({ configured, done }: { configured: boolean; done: () => void }) {
  const [password, setPassword] = useState(""); const [code, setCode] = useState(""); const [username, setUsername] = useState(""); const [token, setToken] = useState(""); const [error, setError] = useState("");
  async function submit(event: FormEvent) { event.preventDefault(); try { const result = configured ? await api<{ csrfToken: string }>("/api/auth/login", { method: "POST", body: JSON.stringify({ password }) }) : await api<{ csrfToken: string }>("/api/auth/setup", { method: "POST", body: JSON.stringify({ code, password, factorioUsername: username || null, factorioToken: token || null }) }); csrf = result.csrfToken; done(); } catch (caught) { setError(caught instanceof Error ? caught.message : "Authentication failed."); } }
  return <main className="mx-auto flex min-h-screen max-w-md items-center px-5"><Card className="w-full space-y-5"><div className="flex items-center gap-3"><Gamepad2 className="h-9 w-9 text-yellow-400" /><div><h1 className="text-xl font-bold">Factorio Server Manager</h1><p className="text-sm text-zinc-400">{configured ? "Sign in to manage this server" : "Complete one-time setup"}</p></div></div><form onSubmit={submit} className="space-y-3">{!configured && <><label className="block text-sm">Setup code<input value={code} onChange={event => setCode(event.target.value)} required /></label><label className="block text-sm">Factorio username<input value={username} onChange={event => setUsername(event.target.value)} /></label><label className="block text-sm">Factorio token<input type="password" value={token} onChange={event => setToken(event.target.value)} /></label></>}<label className="block text-sm">Admin password<input type="password" minLength={12} value={password} onChange={event => setPassword(event.target.value)} required /></label>{error && <p className="rounded bg-red-950 p-3 text-sm text-red-300">{error}</p>}<Button className="w-full" type="submit">{configured ? "Sign in" : "Create admin account"}</Button></form></Card></main>;
}

type NavigationItem = readonly [Tab, typeof Activity, string, ownerOnly?: boolean];
const navigation: ReadonlyArray<NavigationItem> = [["overview", Activity, "Overview"], ["settings", Settings2, "Settings"], ["versions", Download, "Versions"], ["mods", Boxes, "Mods"], ["saves", Save, "Saves"], ["players", Users, "Players"], ["logs", TerminalSquare, "Logs"], ["health", HeartPulse, "System Health"], ["users", Users, "Accounts", true], ["audit", Activity, "Audit log", true]];
let currentRole: Me["role"];
const stateClasses: Record<State, string> = { running: "bg-emerald-500/20 text-emerald-300", stopped: "bg-zinc-700 text-zinc-200", starting: "bg-yellow-500/20 text-yellow-300", stopping: "bg-yellow-500/20 text-yellow-300", failed: "bg-red-500/20 text-red-300" };

export function App() {
  const [configured, setConfigured] = useState<boolean>(); const [signedIn, setSignedIn] = useState(false); const [me, setMe] = useState<Me>(); const [tab, setTab] = useState<Tab>("overview"); const [status, setStatus] = useState<Status>(); const [settings, setSettings] = useState<Settings>(); const [logs, setLogs] = useState<string[]>([]); const [error, setError] = useState("");
  const refresh = useCallback(async () => { try { const [nextStatus, nextSettings, nextLogs] = await Promise.all([api<Status>("/api/status"), api<Settings>("/api/settings"), api<string[]>("/api/logs")]); setStatus(nextStatus); setSettings(nextSettings); setLogs(nextLogs); } catch (caught) { setError(caught instanceof Error ? caught.message : "Could not load server state."); } }, []);
  useEffect(() => { api<{ configured: boolean }>("/api/auth/status").then(result => { setConfigured(result.configured); if (result.configured) api<Me>("/api/auth/me").then(current => { csrf = current.csrfToken; setMe(current); setSignedIn(true); }).catch(() => undefined); }).catch(() => setConfigured(false)); }, []);
  useEffect(() => { if (!signedIn) return; void refresh(); const connection = new HubConnectionBuilder().withUrl("/hubs/status").withAutomaticReconnect().build(); connection.on("status", setStatus); connection.on("log", (line: string) => setLogs(current => [...current.slice(-499), `${new Date().toISOString()} ${line}`])); void connection.start(); return () => { void connection.stop(); }; }, [signedIn, refresh]);
  const action: Action = async (path, init = { method: "POST" }) => { try { setError(""); await api(path, init); await refresh(); return true; } catch (caught) { setError(caught instanceof Error ? caught.message : "Request failed."); return false; } };
  async function finishSignIn() { try { const current = await api<Me>("/api/auth/me"); setMe(current); setSignedIn(true); } catch (caught) { setError(caught instanceof Error ? caught.message : "Authentication failed."); } }
  if (configured === undefined) return <main className="p-8 text-zinc-400">Loading…</main>;
  if (!signedIn) return <Auth configured={configured} done={() => void finishSignIn()} />;
  const visibleNavigation = navigation.filter(([, , , ownerOnly]) => !ownerOnly || me?.role === "owner");
  const title = navigation.find(item => item[0] === tab)?.[2];
  if ((tab === "users" || tab === "audit") && me?.role !== "owner") return <main className="mx-auto w-full max-w-6xl p-5 md:p-8"><Card><h2 className="font-semibold">Forbidden</h2><p className="mt-2 text-sm text-zinc-400">Owner permissions are required to view this page.</p><Button className="mt-4" onClick={() => setTab("overview")}>Back to overview</Button></Card></main>;
  if (tab === "users" && me?.role === "owner") return <main className="mx-auto w-full max-w-6xl p-5 md:p-8"><Accounts /></main>;
  if (tab === "audit" && me?.role === "owner") return <main className="mx-auto w-full max-w-6xl p-5 md:p-8"><AuditLog /></main>;
  return <div className="min-h-screen md:grid md:grid-cols-[15rem_1fr]"><aside className="border-b border-zinc-800 bg-zinc-900/50 p-4 md:min-h-screen md:border-b-0 md:border-r"><div className="mb-7 flex items-center gap-2 font-bold"><Gamepad2 className="text-yellow-400" />Factorio Manager</div><nav className="flex gap-2 overflow-x-auto md:flex-col">{visibleNavigation.map(([id, Icon, label]) => <button key={id} onClick={() => setTab(id)} className={`flex items-center gap-3 rounded-md px-3 py-2 text-sm ${tab === id ? "bg-yellow-400 text-zinc-950" : "text-zinc-300 hover:bg-zinc-800"}`}><Icon size={17} />{label}</button>)}</nav><Button variant="outline" className="mt-8 w-full" onClick={() => void action("/api/auth/logout").then(() => { csrf = ""; setSignedIn(false); })}><LogOut size={16} className="mr-2" />Sign out</Button></aside><main className="mx-auto w-full max-w-6xl p-5 md:p-8"><header className="mb-7 flex items-center justify-between"><div><h1 className="text-2xl font-bold">{title}</h1><p className="text-sm text-zinc-400">One container, one Factorio server</p></div>{status && <span className={`rounded-full px-3 py-1 text-xs font-semibold uppercase ${stateClasses[status.state]}`}>{status.state}</span>}</header>{error && <p className="mb-5 rounded bg-red-950 p-3 text-sm text-red-300">{error}</p>}{tab === "overview" && <Overview status={status} settings={settings} action={action} />}{tab === "settings" && settings && <SettingsPage settings={settings} action={action} />}{tab === "versions" && <Versions settings={settings} action={action} />}{tab === "mods" && <Mods action={action} role={me?.role} status={status} />}{tab === "saves" && <Saves action={action} role={me?.role} />}{tab === "players" && <Players action={action} role={me?.role} />}{tab === "logs" && <Logs logs={logs} />}{tab === "health" && <Health />}</main></div>;
}

function Accounts() {
  const [users, setUsers] = useState<User[]>([]); const [username, setUsername] = useState(""); const [password, setPassword] = useState(""); const [role, setRole] = useState<"admin"|"viewer">("viewer"); const [error, setError] = useState("");
  const load = useCallback(() => { void api<User[]>("/api/users").then(setUsers).catch(e => setError(e instanceof Error ? e.message : "Forbidden")); }, []); useEffect(load, [load]);
  async function create() { try { await api("/api/users", { method: "POST", body: JSON.stringify({ username, password, role }) }); setUsername(""); setPassword(""); load(); } catch (e) { setError(e instanceof Error ? e.message : "Could not create account."); } }
  async function changeRole(u: User, next: string) { if (!window.confirm(`Change ${u.username}'s role?`)) return; try { await api(`/api/users/${u.id}/role`, { method: "PATCH", body: JSON.stringify({ role: next }) }); load(); } catch (e) { setError(e instanceof Error ? e.message : "Role change failed."); } }
  async function resetPassword(u: User) { const next = window.prompt("New password (at least 12 characters)"); if (!next || next.length < 12 || !window.confirm(`Reset ${u.username}'s password?`)) return; try { await api(`/api/users/${u.id}/password`, { method: "POST", body: JSON.stringify({ password: next }) }); setError("Password reset successfully."); } catch (e) { setError(e instanceof Error ? e.message : "Password reset failed."); } }
  return <div className="space-y-5"><Card className="space-y-3"><h2 className="font-semibold">Accounts</h2><div className="grid gap-2 md:grid-cols-4"><input placeholder="Username" value={username} onChange={e=>setUsername(e.target.value)} /><input type="password" placeholder="Temporary password" value={password} onChange={e=>setPassword(e.target.value)} /><select value={role} onChange={e=>setRole(e.target.value as typeof role)}><option value="viewer">Viewer</option><option value="admin">Admin</option></select><Button onClick={()=>void create()} disabled={!username || password.length<12}>Create</Button></div>{error&&<p className="text-sm text-red-300">{error}</p>}</Card><Card><div className="space-y-2">{users.map(u=><div key={u.id} className="flex flex-wrap items-center justify-between gap-2 rounded border border-zinc-800 p-3 text-sm"><span>{u.username} <span className="text-zinc-500">({u.role})</span></span>{u.role!=="owner"&&<div className="flex gap-2"><select value={u.role} onChange={e=>void changeRole(u,e.target.value)}><option value="viewer">Viewer</option><option value="admin">Admin</option></select><Button size="sm" variant="outline" onClick={()=>void resetPassword(u)}>Reset password</Button><Button size="sm" variant="destructive" onClick={()=>{if(window.confirm(`Delete ${u.username}?`)) void api(`/api/users/${u.id}`,{method:"DELETE"}).then(load)}}><Trash2 size={15}/></Button></div>}</div>)}</div></Card></div>;
}

function AuditLog() { const [events,setEvents]=useState<AuditEvent[]>([]); const [before,setBefore]=useState<number>(); const load=useCallback(()=>{const q=before?`?beforeId=${before}&limit=50`:"?limit=50"; void api<AuditEvent[]>(`/api/audit-events${q}`).then(setEvents);},[before]); useEffect(load,[load]); return <Card><h2 className="mb-3 font-semibold">Audit log</h2><div className="space-y-2">{events.map(e=><div key={e.id} className="flex justify-between rounded border border-zinc-800 p-3 text-sm"><span>{new Date(e.occurredAtUtc).toLocaleString()} · {e.action}</span><span className={e.outcome==="success"?"text-emerald-300":e.outcome==="denied"?"text-amber-300":"text-red-300"}>{e.outcome}</span></div>)}</div><Button className="mt-4" variant="outline" disabled={!events.length} onClick={()=>setBefore(events.at(-1)?.id)}>Older</Button></Card>; }

function Logs({ logs }: { logs: string[] }) {
  const [query, setQuery] = useState("");
  const filtered = query.trim() ? logs.filter(line => line.toLowerCase().includes(query.toLowerCase())) : logs;
  return <Card><div className="mb-3 flex flex-wrap gap-2"><label className="flex min-w-0 flex-1 items-center gap-2"><Search size={16} className="text-zinc-500" /><input placeholder="Filter logs" value={query} onChange={event => setQuery(event.target.value)} /></label><Button variant="outline" onClick={() => { window.location.href = "/api/logs/download"; }}><Download className="mr-2" size={16} />Download</Button></div><p className="mb-2 text-xs text-zinc-500">Showing {filtered.length} of {logs.length} in-memory lines. The server rotates the file at 10 MB.</p><pre className="max-h-[65vh] overflow-auto whitespace-pre-wrap break-words font-mono text-xs text-zinc-300">{filtered.join("\n") || "No matching server output."}</pre></Card>;
}

function Health() {
  const [health, setHealth] = useState<SystemHealth>();
  const [maintenance, setMaintenance] = useState<MaintenanceStatus>();
  const [error, setError] = useState("");
  const load = useCallback(async () => { try { const [nextHealth, nextMaintenance] = await Promise.all([api<SystemHealth>("/api/system-health"), api<MaintenanceStatus>("/api/maintenance")]); setHealth(nextHealth); setMaintenance(nextMaintenance); setError(""); } catch (caught) { setError(caught instanceof Error ? caught.message : "Could not load system health."); } }, []);
  useEffect(() => { void load(); const timer = window.setInterval(() => void load(), 15000); return () => window.clearInterval(timer); }, [load]);
  const bytes = (value?: number) => value === undefined ? "—" : `${(value / 1024 / 1024 / 1024).toFixed(1)} GB`;
  const uptime = (seconds = 0) => `${Math.floor(seconds / 86400)}d ${Math.floor(seconds / 3600) % 24}h ${Math.floor(seconds / 60) % 60}m`;
  if (error) return <Card><p className="text-sm text-red-300">{error}</p></Card>;
  if (!health || !maintenance) return <Card><p className="text-sm text-zinc-400">Loading system health…</p></Card>;
  const date = (value?: string) => value ? new Date(value).toLocaleString() : "ยังไม่มีข้อมูล";
  return <div className="grid gap-5 md:grid-cols-2"><Card><h2 className="mb-4 font-semibold">Runtime health</h2><dl className="space-y-3 text-sm"><div className="flex justify-between"><dt className="text-zinc-400">Uptime</dt><dd>{uptime(health.uptimeSeconds)}</dd></div><div className="flex justify-between"><dt className="text-zinc-400">Working set</dt><dd>{bytes(health.workingSetBytes)}</dd></div><div className="flex justify-between"><dt className="text-zinc-400">Database</dt><dd className="text-emerald-300">{health.databasePresent ? "Available" : "Missing"}</dd></div></dl></Card><Card><h2 className="mb-4 font-semibold">Data inventory</h2><dl className="space-y-3 text-sm"><div className="flex justify-between"><dt className="text-zinc-400">Disk free</dt><dd>{bytes(health.dataFreeBytes)} / {bytes(health.dataTotalBytes)}</dd></div><div className="flex justify-between"><dt className="text-zinc-400">Saves</dt><dd>{health.saveCount}</dd></div><div className="flex justify-between"><dt className="text-zinc-400">Backups</dt><dd>{health.backupCount}</dd></div><div className="flex justify-between"><dt className="text-zinc-400">Cached versions</dt><dd>{health.versionCount}</dd></div><div className="flex justify-between"><dt className="text-zinc-400">Mod archives</dt><dd>{health.modFileCount}</dd></div></dl></Card><Card className="md:col-span-2"><h2 className="mb-4 font-semibold">Scheduled maintenance</h2><dl className="grid gap-3 text-sm md:grid-cols-2"><div><dt className="text-zinc-400">Backup schedule</dt><dd>ทุก {maintenance.backupIntervalHours} ชั่วโมง · เก็บ {maintenance.backupRetention} ชุด</dd></div><div><dt className="text-zinc-400">Last backup</dt><dd>{date(maintenance.lastScheduledBackup)}</dd></div><div><dt className="text-zinc-400">Next backup</dt><dd>{date(maintenance.nextScheduledBackup)}</dd></div><div><dt className="text-zinc-400">Last update check</dt><dd>{date(maintenance.lastUpdateCheck)}</dd></div><div><dt className="text-zinc-400">Next update check</dt><dd>{date(maintenance.nextUpdateCheck)}</dd></div></dl><p className="mt-4 text-xs text-zinc-500">Updated {new Date(health.checkedAt).toLocaleString()}</p></Card></div>;
}

function Overview({ status, settings, action }: { status?: Status; settings?: Settings; action: Action }) { return <div className="grid gap-5 lg:grid-cols-3"><Card className="lg:col-span-2"><h2 className="mb-1 text-lg font-semibold">{settings?.serverName ?? "Server"}</h2><p className="mb-5 text-sm text-zinc-400">{settings?.description}</p><div className="flex flex-wrap gap-3"><Button onClick={() => void action("/api/control/start")} disabled={status?.state === "running" || status?.state === "starting"}><CirclePlay className="mr-2" size={17} />Start</Button><Button variant="destructive" onClick={() => void action("/api/control/stop")} disabled={status?.state !== "running"}><CircleStop className="mr-2" size={17} />Stop</Button><Button variant="secondary" onClick={() => void action("/api/control/restart")} disabled={status?.state !== "running"}>Restart</Button></div>{status?.message && <p className="mt-4 text-sm text-red-300">{status.message}</p>}</Card><Card><h2 className="mb-3 font-semibold">Runtime</h2><dl className="space-y-2 text-sm"><div className="flex justify-between"><dt className="text-zinc-400">Version</dt><dd>{settings?.activeVersion ?? "Not selected"}</dd></div><div className="flex justify-between"><dt className="text-zinc-400">Save</dt><dd>{settings?.activeSave ?? "Not selected"}</dd></div><div className="flex justify-between"><dt className="text-zinc-400">Process</dt><dd>{status?.processId ?? "—"}</dd></div></dl></Card></div>; }

function SettingsPage({ settings, action }: { settings: Settings; action: Action }) {
  const [draft, setDraft] = useState(settings);
  const map = draft.mapGeneration ?? {} as MapGeneration;
  const setMap = (key: keyof MapGeneration, value: unknown) => setDraft({ ...draft, mapGeneration: { ...map, [key]: value } });
  const number = (key: keyof MapGeneration) => ({ type: "number" as const, value: String(map[key] ?? ""), onChange: (event: ChangeEvent<HTMLInputElement>) => setMap(key, Number(event.target.value)) });
  const select = (key: keyof MapGeneration) => ({ value: String(map[key] ?? "normal"), onChange: (event: ChangeEvent<HTMLSelectElement>) => setMap(key, event.target.value) });
  const levels = ["very-low", "low", "normal", "high", "very-high", "none"];
  const resource = (key: keyof MapGeneration, label: string, description: string, includeRichness = true) => { const value = (map[key] ?? {}) as ResourceSettings; const update = (part: keyof ResourceSettings, next: string) => setMap(key, { ...value, [part]: next }); const parts = includeRichness ? (["frequency", "size", "richness"] as const) : (["frequency", "size"] as const); return <div className="rounded border border-zinc-800 p-3"><p className="font-medium">{label}</p><p className="mb-2 text-xs text-zinc-400">{description}</p><div className="grid grid-cols-3 gap-2">{parts.map(part => <label key={part} className="text-xs capitalize">{part === "frequency" ? "ความถี่" : part === "size" ? "ขนาด" : "ความอุดมสมบูรณ์"}<select value={value[part] ?? "normal"} onChange={event => update(part, event.target.value)}>{levels.map(level => <option key={level}>{level}</option>)}</select></label>)}</div></div>; };
  return <form onSubmit={event => { event.preventDefault(); void action("/api/settings", { method: "PUT", body: JSON.stringify(draft) }); }} className="grid gap-5 lg:grid-cols-2">
    <Card className="space-y-3"><h2 className="font-semibold">Server</h2><label className="block text-sm">Server name<input value={draft.serverName} onChange={event => setDraft({ ...draft, serverName: event.target.value })} /></label><label className="block text-sm">Description<input value={draft.description} onChange={event => setDraft({ ...draft, description: event.target.value })} /></label><label className="block text-sm">Max players (0 = unlimited)<input type="number" value={draft.maxPlayers} onChange={event => setDraft({ ...draft, maxPlayers: Number(event.target.value) })} /></label><label className="block text-sm">Autosave minutes<input type="number" value={draft.autosaveMinutes} onChange={event => setDraft({ ...draft, autosaveMinutes: Number(event.target.value) })} /></label></Card>
    <Card className="space-y-3"><h2 className="font-semibold">Maintenance</h2><label className="block text-sm">Backup interval (hours)<input type="number" value={draft.backupIntervalHours} onChange={event => setDraft({ ...draft, backupIntervalHours: Number(event.target.value) })} /></label><label className="block text-sm">Backup retention<input type="number" value={draft.backupRetention} onChange={event => setDraft({ ...draft, backupRetention: Number(event.target.value) })} /></label><label className="block text-sm">Timezone<input value={draft.timeZone} onChange={event => setDraft({ ...draft, timeZone: event.target.value })} /></label><label className="flex items-center gap-2 text-sm"><input className="w-auto" type="checkbox" checked={draft.visibilityPublic} onChange={event => setDraft({ ...draft, visibilityPublic: event.target.checked })} />List publicly</label></Card>
    <Card className="space-y-3 lg:col-span-2"><h2 className="font-semibold">สร้างแผนที่ — Map settings</h2><p className="text-sm text-zinc-400">ค่าด้านล่างตรงกับหน้า New Game ของ Factorio และจะถูกใช้เมื่อกด Create map เท่านั้น การเปลี่ยนค่าจะไม่แก้แผนที่เดิม</p><div className="grid gap-3 md:grid-cols-3"><label className="text-sm">Seed (ว่าง = สุ่ม)<input type="number" value={map.seed ?? ""} onChange={event => setMap("seed", event.target.value ? Number(event.target.value) : undefined)} /></label><label className="text-sm">ความกว้างแผนที่ (tiles)<input type="number" min="0" value={map.width} onChange={event => setMap("width", Number(event.target.value))} /><span className="text-xs text-zinc-500">0 = ไม่จำกัด; ค่าที่กำหนดต้องไม่น้อยกว่า 64</span></label><label className="text-sm">ความสูงแผนที่ (tiles)<input type="number" min="0" value={map.height} onChange={event => setMap("height", Number(event.target.value))} /><span className="text-xs text-zinc-500">0 = ไม่จำกัด; ใช้จำกัดขนาดโลกสำหรับเซิร์ฟเวอร์ที่ต้องการประหยัดพื้นที่</span></label><label className="text-sm">น้ำ — Water<select {...select("water")}>{levels.map(level => <option key={level}>{level}</option>)}</select><span className="text-xs text-zinc-500">ความถี่และขนาดของทะเลสาบ/แม่น้ำ</span></label><label className="text-sm">พื้นที่เริ่มต้น<select {...select("startingArea")}>{levels.map(level => <option key={level}>{level}</option>)}</select><span className="text-xs text-zinc-500">พื้นที่ปลอดภัยรอบจุดเริ่มต้น</span></label><label className="text-sm">ความหลากหลายภูมิประเทศ<select {...select("terrainSegmentation")}>{levels.map(level => <option key={level}>{level}</option>)}</select><span className="text-xs text-zinc-500">ขนาดของพื้นที่ทุ่ง/ป่า/ภูเขา</span></label><label className="flex items-center gap-2 text-sm"><input className="w-auto" type="checkbox" checked={map.peacefulMode} onChange={event => setMap("peacefulMode", event.target.checked)} />Peaceful mode — ศัตรูไม่โจมตีก่อน</label></div></Card>
    <Card className="space-y-3 lg:col-span-2"><h2 className="font-semibold">ทรัพยากร — Resources</h2><p className="text-xs text-zinc-400">ความถี่ = จำนวนแหล่ง, ขนาด = พื้นที่แหล่ง, ความอุดมสมบูรณ์ = ปริมาณต่อแหล่ง ระดับ none ปิดทรัพยากรนั้น</p><div className="grid gap-3 md:grid-cols-2">{resource("ironOre", "Iron ore", "แร่เหล็กสำหรับแผ่นเหล็กและเครื่องจักร")} {resource("copperOre", "Copper ore", "แร่ทองแดงสำหรับวงจรและสายไฟ")} {resource("stone", "Stone", "หินสำหรับเตาและสิ่งก่อสร้าง")} {resource("coal", "Coal", "ถ่านหินสำหรับเชื้อเพลิงและพลาสติก")} {resource("uraniumOre", "Uranium ore", "แร่ยูเรเนียมสำหรับพลังงานนิวเคลียร์")} {resource("crudeOil", "Crude oil", "บ่อน้ำมันสำหรับผลิตภัณฑ์ปิโตรเลียม")} {resource("trees", "Trees", "ความถี่และขนาดของกลุ่มต้นไม้ในแผนที่", false)}</div></Card>
    <Card className="space-y-3"><h2 className="font-semibold">ศัตรูและการขยายฐาน</h2>{resource("enemyBase", "Enemy bases", "ความถี่ ขนาด และความแข็งแกร่งของฐานศัตรูที่สร้างบนแผนที่")}<label className="flex items-center gap-2 text-sm"><input className="w-auto" type="checkbox" checked={map.enemyExpansionEnabled} onChange={event => setMap("enemyExpansionEnabled", event.target.checked)} />เปิดการขยายฐานศัตรู</label><label className="text-sm">ระยะผู้เล่นขั้นต่ำ<input {...number("enemyExpansionMinDistance")} /><span className="text-xs text-zinc-500">ระยะห่างขั้นต่ำจากผู้เล่น (หน่วย chunk) ที่กลุ่มขยายฐานจะเริ่มตั้งฐานใหม่</span></label><label className="text-sm">ระยะขยายสูงสุด<input {...number("enemyExpansionMaxDistance")} /><span className="text-xs text-zinc-500">ระยะไกลสุดจากฐานเดิมที่อนุญาตให้เลือกตำแหน่งฐานใหม่ ยิ่งสูงยิ่งกระจายไกล</span></label><label className="text-sm">ขนาดกลุ่มผู้ตั้งถิ่นฐานขั้นต่ำ<input {...number("settlerGroupMinSize")} /><span className="text-xs text-zinc-500">จำนวนยูนิตขั้นต่ำในกลุ่มที่เดินทางไปสร้างฐานใหม่</span></label><label className="text-sm">ขนาดกลุ่มผู้ตั้งถิ่นฐานสูงสุด<input {...number("settlerGroupMaxSize")} /><span className="text-xs text-zinc-500">จำนวนยูนิตสูงสุดในกลุ่มขยายฐาน ยิ่งมากยิ่งป้องกันกลุ่มได้ดี</span></label><label className="text-sm">คูลดาวน์ขยายฐานขั้นต่ำ (นาที)<input {...number("expansionMinCooldown")} /><span className="text-xs text-zinc-500">เวลาขั้นต่ำระหว่างการพยายามขยายฐานแต่ละครั้ง ระบบจะแปลงเป็น ticks ให้ Factorio</span></label><label className="text-sm">คูลดาวน์ขยายฐานสูงสุด (นาที)<input {...number("expansionMaxCooldown")} /><span className="text-xs text-zinc-500">เวลาสูงสุดที่สุ่มรอก่อนการขยายครั้งถัดไป ต้องไม่น้อยกว่าค่าขั้นต่ำ</span></label></Card>
    <Card className="space-y-3"><h2 className="font-semibold">วิวัฒนาการและหน้าผา</h2><p className="text-xs text-zinc-400">เปอร์เซ็นต์คือสัดส่วนผลกระทบต่อ evolution factor: เวลา มลพิษ และการทำลายฐานศัตรู ยิ่งสูงศัตรูยิ่งแข็งเร็ว</p><label className="text-sm">Evolution จากเวลา (%)<input {...number("evolutionTime")} /></label><label className="text-sm">Evolution จากมลพิษ (%)<input {...number("evolutionPollution")} /></label><label className="text-sm">Evolution จากการทำลายฐาน (%)<input {...number("evolutionDestroy")} /></label><label className="text-sm">ระยะระดับหน้าผา<input {...number("cliffElevationInterval")} /><span className="text-xs text-zinc-500">ความสูงภูมิประเทศที่ต้องเปลี่ยนก่อนสร้างชั้นหน้าผา ค่าสูงทำให้หน้าผาห่างกัน</span></label><label className="text-sm">Offset ระดับหน้าผา<input {...number("cliffElevationOffset")} /><span className="text-xs text-zinc-500">เลื่อนระดับความสูงอ้างอิงของหน้าผา ใช้ปรับจังหวะการเกิดหน้าผาบนแผนที่</span></label><label className="text-sm">ความอุดมสมบูรณ์ของหน้าผา<select {...select("cliffRichness")}>{levels.map(level => <option key={level}>{level}</option>)}</select><span className="text-xs text-zinc-500">ระดับความหนาแน่น/ความถี่ของแนวหน้าผา none คือปิดหน้าผา</span></label></Card>
    <div className="lg:col-span-2"><Button type="submit"><Settings2 className="mr-2" size={16} />Save settings</Button></div>
    <PasswordCard action={action} />
  </form>;
}

function PasswordCard({ action }: { action: Action }) {
  const [currentPassword, setCurrentPassword] = useState(""); const [newPassword, setNewPassword] = useState(""); const [confirmation, setConfirmation] = useState(""); const [message, setMessage] = useState("");
  async function submit() { setMessage(""); if (newPassword.length < 12) { setMessage("New password must be at least 12 characters."); return; } if (newPassword !== confirmation) { setMessage("New passwords do not match."); return; } if (await action("/api/auth/password", { method: "POST", body: JSON.stringify({ currentPassword, newPassword }) })) { setCurrentPassword(""); setNewPassword(""); setConfirmation(""); setMessage("Password changed."); } }
  return <Card className="space-y-3 lg:col-span-2"><h2 className="font-semibold">Change admin password</h2><p className="text-xs text-zinc-400">ใช้รหัสผ่านใหม่อย่างน้อย 12 ตัวอักษร การเปลี่ยนรหัสผ่านจะไม่ทำให้ session ปัจจุบันหลุดออก</p><div className="grid gap-3 md:grid-cols-3"><input type="password" placeholder="Current password" value={currentPassword} onChange={event => setCurrentPassword(event.target.value)} /><input type="password" minLength={12} placeholder="New password" value={newPassword} onChange={event => setNewPassword(event.target.value)} /><input type="password" minLength={12} placeholder="Confirm new password" value={confirmation} onChange={event => setConfirmation(event.target.value)} /><div className="md:col-span-3 flex items-center gap-3"><Button type="button" onClick={() => void submit()}>Change password</Button>{message && <span className="text-sm text-zinc-400">{message}</span>}</div></div></Card>;
}

function Versions({ settings, action }: { settings?: Settings; action: Action }) {
  const [version, setVersion] = useState(settings?.activeVersion ?? "");
  const [channel, setChannel] = useState<"stable" | "experimental">(settings?.channel ?? "stable");
  const [cached, setCached] = useState<string[]>([]);
  const [update, setUpdate] = useState<UpdateStatus>();
  const [checking, setChecking] = useState(false);
  const load = useCallback(async () => {
    const [nextCached, nextUpdate] = await Promise.all([api<string[]>("/api/versions"), api<UpdateStatus | null>("/api/updates")]);
    setCached(nextCached); setUpdate(nextUpdate ?? undefined);
  }, []);
  useEffect(() => { void load(); }, [load]);
  async function checkForUpdates() {
    setChecking(true);
    try { setUpdate(await api<UpdateStatus>("/api/updates/check", { method: "POST" })); } finally { setChecking(false); }
  }
  const checkedAt = update?.checkedAt ? new Date(update.checkedAt).toLocaleString() : "never";
  return <div className="grid gap-5 lg:grid-cols-2">
    <Card className="space-y-3">
      <div className="flex items-center justify-between"><h2 className="font-semibold">Version</h2><Button size="sm" variant="outline" onClick={() => void checkForUpdates()} disabled={checking || !settings?.activeVersion}><RefreshCw className={`mr-2 ${checking ? "animate-spin" : ""}`} size={15} />{checking ? "Checking…" : "Check for updates"}</Button></div>
      {update?.availableVersion ? <div className="rounded border border-yellow-500/50 bg-yellow-500/10 p-3 text-sm text-yellow-200"><p className="font-semibold">Update available: {update.availableVersion}</p><p className="mt-1 text-yellow-100/70">Automatic updates are disabled. A recovery backup is created before Apply.</p></div> : update?.error ? <p className="rounded bg-red-950 p-3 text-sm text-red-300">Update check failed: {update.error}</p> : <p className="text-xs text-zinc-500">Last checked: {checkedAt}</p>}
      <select value={channel} onChange={event => setChannel(event.target.value as typeof channel)}><option value="stable">Stable</option><option value="experimental">Experimental</option></select><input placeholder="e.g. 2.0.67" value={version} onChange={event => setVersion(event.target.value)} /><Button onClick={() => void action(`/api/versions/download/${channel}/${encodeURIComponent(version)}`).then(load)} disabled={!version}><Download className="mr-2" size={16} />Download</Button><Button variant="secondary" onClick={() => { if (window.confirm(`Apply Factorio ${version}? The active save will be backed up first and the server may restart.`)) void action("/api/versions/apply", { method: "POST", body: JSON.stringify({ version, channel }) }).then(load); }} disabled={!version}>Apply selected version</Button>
    </Card>
    <Card><h2 className="mb-3 font-semibold">Cached versions</h2><div className="space-y-2">{cached.length ? cached.map(item => <button key={item} className={`block w-full rounded border px-3 py-2 text-left text-sm ${item === version ? "border-yellow-400" : "border-zinc-700"}`} onClick={() => setVersion(item)}>{item}</button>) : <p className="text-sm text-zinc-400">No server versions downloaded.</p>}</div></Card>
  </div>;
}

function Mods({ action, role, status }: { action: Action; role?: Me["role"]; status?: Status }) {
  const [query, setQuery] = useState(""); const [results, setResults] = useState<PortalMod[]>([]); const [installed, setInstalled] = useState<Mod[]>([]); const [updates, setUpdates] = useState<ModUpdateInfo[]>([]); const [profiles, setProfiles] = useState<ModProfile[]>([]); const [profileName, setProfileName] = useState(""); const [file, setFile] = useState<File>(); const [filter, setFilter] = useState("all"); const [checking, setChecking] = useState(false); const [message, setMessage] = useState(""); const [recovery, setRecovery] = useState<ModRecovery>(); const [preview, setPreview] = useState<ModPreflight>();
  const canMutate = (role === "owner" || role === "admin") && status?.state === "stopped";
  const load = useCallback(async () => { try { const [mods, ps, pending] = await Promise.all([api<Mod[]>("/api/mods"), api<ModProfile[]>("/api/mods/profiles"), api<ModRecovery>("/api/mods/recovery")]); setInstalled(mods); setProfiles(ps); setRecovery(pending); } catch (e) { setMessage(e instanceof Error ? e.message : "Could not load mods."); } }, []);
  useEffect(() => { void load(); }, [load]);
  async function search(event: FormEvent) { event.preventDefault(); try { setResults((await api<{ results?: PortalMod[] }>(`/api/mods/search?query=${encodeURIComponent(query)}`)).results ?? []); } catch (e) { setMessage(e instanceof Error ? e.message : "Mod search failed."); setResults([]); } }
  async function checkUpdates() { setChecking(true); try { setUpdates(await api<ModUpdateInfo[]>("/api/mods/updates")); } catch (e) { setMessage(e instanceof Error ? e.message : "Update check failed."); } finally { setChecking(false); } }
  async function preflight(operation: string, names: string[] = []) { try { const result = await api<ModPreflight>("/api/mods/preflight", { method: "POST", body: JSON.stringify({ operation, names }) }); setPreview(result); return result; } catch (e) { setMessage(e instanceof Error ? e.message : "Preflight failed."); return undefined; } }
  async function mutate(path: string, init: RequestInit, success: string): Promise<boolean> { if (!canMutate) return false; const succeeded = await action(path, init); if (succeeded) { setMessage(success); setPreview(undefined); await load(); } return succeeded; }
  async function install(name: string) { const check = await preflight("install", [name]); if (!canMutate || check?.blockers.length || !window.confirm(`${name} and required dependencies will be installed. Continue?`)) return; await mutate("/api/mods/install", { method: "POST", body: JSON.stringify({ name, enabled: true, includeDependencies: true, confirm: true }) }, `${name} installed.`); }
  async function upload() { if (!file || !canMutate) return; const check = await preflight("upload", [file.name]); if (check?.blockers.length || !window.confirm(`Upload ${file.name} and resolve required dependencies?`)) return; const form = new FormData(); form.append("file", file); form.append("enabled", "true"); form.append("includeDependencies", "true"); if (await mutate("/api/mods/upload", { method: "POST", body: form }, `${file.name} uploaded.`)) setFile(undefined); }
  async function uninstall(mod: Mod) { if (!canMutate || !window.confirm(`Uninstall ${mod.name}?`)) return; try { await api(`/api/mods/${encodeURIComponent(mod.name)}`, { method: "DELETE" }); setMessage(`${mod.name} uninstalled.`); await load(); } catch (e) { const text = e instanceof Error ? e.message : "Uninstall failed."; setMessage(text); if (role === "owner" && text.toLowerCase().includes("dependents") && window.confirm(`${text}\n\nForce uninstall and disable dependents?`)) await mutate(`/api/mods/${encodeURIComponent(mod.name)}?force=true`, { method: "DELETE" }, `${mod.name} forcibly uninstalled.`); } }
  async function bulkUpdate() { const names = updates.filter(x => x.updateAvailable).map(x => x.name); const check = await preflight("bulk-update", names); if (!canMutate || !names.length || check?.blockers.length || !window.confirm(`Update ${names.length} mod(s) atomically?`)) return; await mutate("/api/mods/bulk-update", { method: "POST", body: JSON.stringify({ names, confirm: true }) }, `${names.length} mod(s) updated.`); }
  async function update(mod: Mod) { const check = await preflight("update", [mod.name]); if (!canMutate || check?.blockers.length || !window.confirm(`Update ${mod.name} and required dependencies?`)) return; await mutate(`/api/mods/${encodeURIComponent(mod.name)}/update`, { method: "POST" }, `${mod.name} updated.`); }
  async function saveProfile() { const name = profileName.trim(); if (!name) return; const saved = await mutate("/api/mods/profiles", { method: "POST", body: JSON.stringify({ name, mods: installed.map(m => ({ name: m.name, version: m.version, enabled: m.enabled })) }) }, `Profile “${name}” saved.`); if (saved) setProfileName(""); }
  async function applyProfile(profile: ModProfile) { const check = await preflight("profile-apply", profile.mods.map(m => m.name)); if (!canMutate || check?.blockers.length || !window.confirm(`Apply profile ${profile.name}? Missing pinned versions will be downloaded.`)) return; await mutate(`/api/mods/profiles/${encodeURIComponent(profile.name)}/apply`, { method: "POST" }, `Profile “${profile.name}” applied.`); }
  async function toggle(mod: Mod) { const check = await preflight(mod.enabled ? "disable" : "enable", [mod.name]); if (!check?.blockers.length && window.confirm(`${mod.enabled ? "Disable" : "Enable"} ${mod.name}?`)) await mutate(`/api/mods/${encodeURIComponent(mod.name)}/enabled/${!mod.enabled}`, { method: "POST" }, `${mod.name} ${mod.enabled ? "disabled" : "enabled"}.`); }
  const visible = installed.filter(mod => filter === "all" || filter === "enabled" && mod.enabled || filter === "disabled" && !mod.enabled || filter === "local" && mod.source === "local" || filter === "portal" && mod.source !== "local");
  return <div className="space-y-5">
    {recovery?.pending && <Card className="border border-red-500/50 bg-red-950/30"><p className="font-semibold text-red-200">Mod recovery required</p><p className="mt-1 text-sm text-red-300">{recovery.message}</p><p className="mt-1 text-xs text-red-200/70">The next safe mod operation will restore the previous transaction. Quarantined files: {recovery.quarantinedFiles.length}.</p></Card>}
    <Card className="space-y-3"><h2 className="font-semibold">Mod Portal</h2><form onSubmit={search} className="flex gap-2"><input placeholder="Search mods" value={query} onChange={event => setQuery(event.target.value)} /><Button type="submit"><Search className="mr-2" size={16} />Search</Button></form>{results.map(mod => <div key={mod.name} className="rounded border border-zinc-800 p-3"><p className="font-medium">{mod.title ?? mod.name}</p><p className="mb-2 text-xs text-zinc-400">{mod.summary}</p>{canMutate && <Button size="sm" onClick={() => void install(mod.name)}>Install with dependencies</Button>}</div>)}<div className="flex flex-wrap items-center gap-2 border-t border-zinc-800 pt-3"><input type="file" accept=".zip" onChange={event => setFile(event.target.files?.[0])} /><Button size="sm" variant="secondary" disabled={!file || !canMutate} onClick={() => void upload()}><Upload className="mr-2" size={15} />Upload local zip</Button></div></Card>
    <Card><div className="mb-3 flex flex-wrap items-center justify-between gap-2"><h2 className="font-semibold">Installed</h2><div className="flex flex-wrap gap-2"><select value={filter} onChange={event => setFilter(event.target.value)}><option value="all">All sources/status</option><option value="enabled">Enabled</option><option value="disabled">Disabled</option><option value="portal">Portal</option><option value="local">Local</option></select><Button size="sm" variant="outline" onClick={() => void checkUpdates()} disabled={checking}>{checking ? "Checking…" : "Check updates"}</Button>{canMutate && <Button size="sm" disabled={!updates.some(x => x.updateAvailable)} onClick={() => void bulkUpdate()}>Update all safely</Button>}</div></div>{message && <p className="mb-3 rounded bg-amber-950 p-2 text-sm text-amber-200">{message}</p>}{preview && <div className={`mb-3 rounded border p-3 text-sm ${preview.blockers.length ? "border-red-500/50 bg-red-950/30" : "border-emerald-500/50 bg-emerald-950/20"}`}><p className="font-semibold">Preflight: {preview.operation}</p>{preview.warnings.map(w => <p key={w} className="text-amber-300">Warning: {w}</p>)}{preview.blockers.map(b => <p key={b} className="text-red-300">Blocked: {b}</p>)}{!preview.blockers.length && <p className="text-emerald-300">Ready. {preview.requiresBackup ? "A save backup will be created automatically." : "No save backup is needed."}</p>}</div>}{!canMutate && <p className="mb-3 text-xs text-zinc-500">Mod changes require owner/admin access and a stopped server.</p>}{visible.length ? <div className="space-y-2">{visible.map(mod => { const updateInfo = updates.find(item => item.name.toLowerCase() === mod.name.toLowerCase()); return <div key={mod.name} className="rounded border border-zinc-800 p-3 text-sm"><div className="flex flex-wrap items-center justify-between gap-2"><span>{mod.name} <span className="text-zinc-500">{mod.version}</span> <span className="ml-2 rounded bg-zinc-800 px-2 py-0.5 text-xs text-zinc-400">{mod.source ?? "portal"}</span></span>{canMutate && <div className="flex gap-2">{updateInfo?.updateAvailable && <Button size="sm" onClick={() => void update(mod)}>Update</Button>}<Button size="sm" variant={mod.enabled ? "secondary" : "outline"} onClick={() => void toggle(mod)}>{mod.enabled ? "Disable" : "Enable"}</Button><Button size="sm" variant="destructive" onClick={() => void uninstall(mod)}><Trash2 size={15} /></Button></div>}</div>{mod.factorioVersionRequirement && <p className="mt-2 text-xs text-zinc-400">Factorio requirement: {mod.factorioVersionRequirement}</p>}{updateInfo?.missingDependencies.length ? <p className="mt-2 text-xs text-amber-300">Missing dependencies: {updateInfo.missingDependencies.join(", ")}</p> : mod.dependencies?.length ? <p className="mt-2 text-xs text-zinc-500">Dependencies: {mod.dependencies.join(", ")}</p> : null}{mod.sha256 && <p className="mt-1 truncate text-xs text-zinc-600">SHA-256: {mod.sha256}</p>}</div>; })}</div> : <p className="text-sm text-zinc-400">No mods match this filter.</p>}</Card>
    <Card className="space-y-3 lg:col-span-2"><div className="flex flex-wrap items-center justify-between gap-2"><h2 className="font-semibold">Pinned profiles</h2>{canMutate && <div className="flex gap-2"><input placeholder="Profile name" value={profileName} onChange={e => setProfileName(e.target.value)} /><Button size="sm" onClick={() => void saveProfile()} disabled={!profileName.trim()}>Save current</Button></div>}</div>{profiles.length ? <div className="space-y-2">{profiles.map(profile => <div key={profile.name} className="flex flex-wrap items-center justify-between gap-2 rounded border border-zinc-800 p-3 text-sm"><span>{profile.name} <span className="text-zinc-500">({profile.mods.length} pinned versions)</span></span>{canMutate && <div className="flex gap-2"><Button size="sm" variant="outline" onClick={() => void applyProfile(profile)}>Apply profile</Button><Button size="sm" variant="destructive" onClick={() => { if (window.confirm(`Delete profile ${profile.name}?`)) void mutate(`/api/mods/profiles/${encodeURIComponent(profile.name)}`, { method: "DELETE" }, `Profile “${profile.name}” deleted.`); }}>Delete</Button></div>}</div>)}</div> : <p className="text-sm text-zinc-400">No saved profiles.</p>}</Card>
  </div>;
}

type BackupMetadata = { id: string; fileName: string; sourceSave: string; length: number; sha256: string; createdAtUtc: string; updatedAtUtc: string };
function Saves({ action, role }: { action: Action; role?: Me["role"] }) { const [file, setFile] = useState<File>(); const [name, setName] = useState(""); const [saves, setSaves] = useState<string[]>([]); const [backups, setBackups] = useState<BackupMetadata[]>([]); const owner = role === "owner"; const load = useCallback(() => { void Promise.all([api<string[]>("/api/saves"), api<BackupMetadata[]>("/api/backups")]).then(([nextSaves, nextBackups]) => { setSaves(nextSaves); setBackups(nextBackups); }).catch(() => undefined); }, []); useEffect(load, [load]); async function upload() { if (!file) return; const form = new FormData(); form.append("file", file); if (await action("/api/saves/upload", { method: "POST", body: form })) load(); } function download(id: string) { window.open(`/api/backups/${encodeURIComponent(id)}/download`, "_blank", "noopener"); } async function restore(backup: BackupMetadata) { if (!owner || !window.confirm(`Restore ${backup.fileName} to ${backup.sourceSave}? The current save will be replaced.`)) return; if (await action(`/api/backups/${encodeURIComponent(backup.id)}/restore`, { method: "POST", body: JSON.stringify({ confirm: true }) })) load(); } async function rename(backup: BackupMetadata) { const next = window.prompt("New backup filename (.zip)", backup.fileName); if (!next || next === backup.fileName) return; if (await action(`/api/backups/${encodeURIComponent(backup.id)}`, { method: "PATCH", body: JSON.stringify({ name: next }) })) load(); } async function remove(backup: BackupMetadata) { if (!window.confirm(`Delete ${backup.fileName}?`)) return; if (await action(`/api/backups/${encodeURIComponent(backup.id)}`, { method: "DELETE" })) load(); } return <div className="grid gap-5 lg:grid-cols-2"><Card className="space-y-3"><h2 className="font-semibold">Saves</h2><div className="flex gap-2"><input placeholder="New map name" value={name} onChange={event => setName(event.target.value)} /><Button variant="secondary" onClick={() => void action("/api/saves/create", { method: "POST", body: JSON.stringify({ name }) }).then(load)} disabled={!name}>Create</Button></div><input type="file" accept=".zip" onChange={event => setFile(event.target.files?.[0])} /><Button onClick={() => void upload()} disabled={!file}><Save className="mr-2" size={16} />Upload</Button><div className="space-y-2">{saves.map(save => <div key={save} className="flex items-center justify-between rounded border border-zinc-800 p-2 text-sm"><span>{save}</span><Button size="sm" variant="outline" onClick={() => void action(`/api/saves/select/${encodeURIComponent(save)}`)}>Use</Button></div>)}</div></Card><Card><h2 className="mb-3 font-semibold">Backups</h2><Button variant="secondary" onClick={() => void action("/api/saves/backup").then(load)}><FolderArchive className="mr-2" size={16} />Create backup</Button><div className="mt-4 space-y-2">{backups.map(backup => <div key={backup.id} className="rounded border border-zinc-800 p-2 text-sm"><div className="flex items-center justify-between"><span className="truncate">{backup.fileName}</span><div className="flex gap-1"><Button size="sm" variant="outline" onClick={() => download(backup.id)}><Download size={15} /></Button>{owner && <><Button size="sm" variant="outline" onClick={() => void rename(backup)}>Rename</Button><Button size="sm" variant="destructive" onClick={() => void remove(backup)}><Trash2 size={15} /></Button><Button size="sm" variant="outline" onClick={() => void restore(backup)}><ArchiveRestore size={15} /></Button></>}</div></div><p className="mt-1 text-xs text-zinc-500">{backup.sourceSave} · {backup.length.toLocaleString()} bytes · {backup.createdAtUtc ? new Date(backup.createdAtUtc).toLocaleString() : "unknown"}</p><p className="truncate text-xs text-zinc-600">SHA-256: {backup.sha256}</p></div>)}</div></Card></div>; }

function Players({ action, role }: { action: Action; role?: Me["role"] }) { const [kind, setKind] = useState("admins"); const [name, setName] = useState(""); const [players, setPlayers] = useState<string[]>([]); const [live, setLive] = useState<LivePlayer[]>([]); const [message, setMessage] = useState(""); const canMutate = role === "owner" || role === "admin"; const load = useCallback(() => { void api<string[]>(`/api/players/${kind}`).then(setPlayers); }, [kind]); const loadLive = useCallback(() => { void api<LivePlayer[]>("/api/live-players").then(setLive).catch(e => setMessage(e instanceof Error ? e.message : "Live players unavailable.")); }, []); useEffect(load, [load]); useEffect(() => { loadLive(); const timer = window.setInterval(loadLive, 10000); return () => window.clearInterval(timer); }, [loadLive]); async function control(path: string, body: object, prompt: string) { if (!window.confirm(prompt)) return; await action(path, { method: "POST", body: JSON.stringify(body) }); loadLive(); } return <div className="grid gap-5 lg:grid-cols-2"><Card className="space-y-4"><h2 className="font-semibold">Online players</h2>{message && <p className="rounded bg-amber-950 p-2 text-sm text-amber-300">{message}</p>}<div className="space-y-2">{live.map(player => <div key={player.name} className="flex items-center justify-between rounded border border-zinc-800 p-3 text-sm"><span>{player.name}</span>{canMutate && <div className="flex gap-2"><Button size="sm" variant="outline" onClick={() => void control("/api/live-players/kick", { playerName: player.name }, `Kick ${player.name}?`)}>Kick</Button><Button size="sm" variant="destructive" onClick={() => void control("/api/live-players/ban", { playerName: player.name, reason: "Other" }, `Ban ${player.name}?`)}>Ban</Button></div>}</div>)}{!live.length && <p className="text-sm text-zinc-400">No online players or live control is unavailable.</p>}</div><div className="flex gap-2"><input placeholder="Chat message" value={message.startsWith("RCON") ? "" : message} onChange={event => setMessage(event.target.value)} /><Button disabled={!canMutate || !message.trim()} onClick={() => void control("/api/live-chat", { message }, "Send this chat message?")}>Send chat</Button></div></Card><Card className="max-w-xl space-y-4"><h2 className="font-semibold">Player lists</h2><select value={kind} onChange={event => setKind(event.target.value)}><option value="admins">Admins</option><option value="whitelist">Whitelist</option><option value="bans">Bans</option></select>{canMutate && <div className="flex gap-2"><input placeholder="Factorio player name" value={name} onChange={event => setName(event.target.value)} /><Button onClick={() => void action(`/api/players/${kind}`, { method: "POST", body: JSON.stringify({ playerName: name }) }).then(success => { if (success) { setName(""); load(); } })} disabled={!name}>Add</Button></div>}<div className="space-y-2">{players.map(player => <div key={player} className="flex items-center justify-between rounded border border-zinc-800 p-3 text-sm"><span>{player}</span>{canMutate && <Button size="sm" variant="destructive" onClick={() => void action(`/api/players/${kind}/${encodeURIComponent(player)}`, { method: "DELETE" }).then(load)}><Trash2 size={15} /></Button>}</div>)}{!players.length && <p className="text-sm text-zinc-400">This list is empty.</p>}</div></Card></div>; }
